oxy_webhelp_navlinks = {"irec_hybrid_environments-d39536e60808":{"topics":[{"title":"Full disaster or tenant compromise","shortdesc":"<p class=\"shortdesc\">When both on-premises Active Directory and Microsoft Entra ID are compromised or         unavailable, <span class=\"ph\">RSC<\/span> orchestrates a complete recovery across the full hybrid         identity infrastructure.<\/p>","href":"identity_recovery\/irec_full_disaster_recovery.html","attributes":{"data-id":"irec_full_disaster_recovery"},"menu":{"hasChildren":false},"tocID":"irec_full_disaster_recovery-d39536e60821","topics":[]},{"title":"Ransomware isolated to Active Directory","shortdesc":"<p class=\"shortdesc\">When a ransomware attack is confined to on-premises Active Directory and Microsoft         Entra ID remains operational, <span class=\"ph\">RSC<\/span> performs a targeted recovery that         restores only AD-synced identities.<\/p>","href":"identity_recovery\/irec_ad_ransomware_recovery.html","attributes":{"data-id":"irec_ad_ransomware_recovery"},"menu":{"hasChildren":false},"tocID":"irec_ad_ransomware_recovery-d39536e60835","topics":[]},{"title":"Recovering an AD forest","shortdesc":"<p class=\"shortdesc\">When a ransomware attack or disaster occurs, recover the entire Active Directory         forest to restore all of its domains. <span class=\"ph\">RSC<\/span> provides a master wizard that         combines all the steps to recover the domains.<\/p>","href":"adds\/recovering_ad_forest_2.html","attributes":{"data-id":"recovering_ad_forest"},"menu":{"hasChildren":false},"tocID":"recovering_ad_forest-d39536e60849","topics":[]},{"title":"Post recovery tasks for hybrid identity environments","shortdesc":"<p class=\"shortdesc\">Post-recovery tasks performed outside of <span class=\"ph\">RSC<\/span> finalize the restoration         of a hybrid identity environment.<\/p>","href":"identity_recovery\/irec_hybrid_post_recovery_tasks.html","attributes":{"data-id":"irec_hybrid_post_recovery_tasks"},"menu":{"hasChildren":false},"tocID":"irec_hybrid_post_recovery_tasks-d39536e60863","topics":[]}]}};